from pathlib import Path
import json,runpy
P=Path(__file__).resolve().parent
H=runpy.run_path(str(P/'build_page.py'));globals().update({k:H[k] for k in ['chapter','detail','table','bars','ring','link','photo','C','fmt']})
S=json.loads((P/'downloads/Beppu-Tourism-Supplement.json').read_text());J=json.loads((P/'downloads/Beppu-JTA-Monthly.json').read_text());A=[r for r in J if r['year']==2025];B=[r for r in J if r['year']==2026]
body='<div class="section-head"><span class="section-no" aria-hidden="true">02+</span><div><p class="kicker">MORE DETAIL / 宿泊と支出の補足</p><h2>泊まる長さと、<br>客室の余白。</h2></div></div><p class="intro">市の入湯税ベースの宿泊数とは別に、観光庁は回答した宿泊施設の実数を市別に公表しています。同じ施設の延べ宿泊者数と実宿泊者数から、1回の宿泊の長さを計算できます。</p>'
nights=sum(r['person_nights_large'] for r in A);people=sum(r['checkins_large'] for r in A)
body+=f'<div class="split"><article class="panel"><span class="scope">2025年・従業者10人以上の回答施設</span><h3>1回の施設宿泊の長さ</h3><p class="big-number" style="color:var(--lime)">{nights/people:.3f}<small>泊</small></p><p class="micro">延べ{fmt(nights)}人泊 ÷ 実宿泊{fmt(people)}人。毎月の対象70施設、回答30〜37施設。月次第2次速報12か月合算。</p></article><article><h3>3つの「泊数」は、同じ数字ではない</h3><p class="intro">上の1.103泊は回答施設での比率。市事業評価の1.106泊は算式等未記載。県内旅行者の「1泊61.7%」は質問紙調査です。別府市の全宿泊者や、日帰りを含む平均滞在に置き換えません。</p><p class="micro">同じ人でも宿を替えれば施設ごとに数えます。1回の別府旅行全体の泊数ではありません。</p></article></div>'
body+='<h3 style="margin-top:35px">2025年・月別客室稼働率</h3>'+bars([(str(r['month'])+'月',r['room_occupancy_pct_large']) for r in A],100,'%',C[2])+'<p class="note">最大は11月68.7%、最小は6月51.9%。ただし月ごとに回答施設が変わります。地域全施設の空室率や、希望する日に予約できる確率とは異なります。</p>'
body+=detail('2025年月別の稼働率・人泊・実人数・回収数と原表',table('別府市・従業者10人以上の回答施設。参考第5〜12表',['月','客室稼働 %','延べ人泊','実宿泊 人','回収施設','原表'],[[str(r['month'])+'月',r['room_occupancy_pct_large'],fmt(r['person_nights_large']),fmt(r['checkins_large']),r['large_facility_respondents'],f'<a href="{r["source_url"]}">Excel ↗</a>'] for r in A],True))
body+=detail('2026年1〜8月の新しい調査区分を見る', '<p class="note warning"><strong>2026年から対象区分が従業者数基準から客室数基準へ変更。</strong>以下は客室20室以上の回答施設（対象62、回収32〜36）。2025年と連続した同一系列の前年比グラフにはしません。</p>'+table('別府市・2026年は客室20室以上の回答施設',['月','客室稼働 %','延べ人泊','実宿泊 人','回収施設','原表'],[[str(r['month'])+'月',r['room_occupancy_pct_large'],fmt(r['person_nights_large']),fmt(r['checkins_large']),r['large_facility_respondents'],f'<a href="{r["source_url"]}">Excel ↗</a>'] for r in B],True))
fees=S['oita_inbound_spending_2025']['segments'];f=fees[0]
body+='<h3 style="margin-top:45px">訪日客の支出費目は、県の参考値として</h3><span class="scope">大分県全体 / 2025年 / 全目的</span><div class="split"><article class="panel"><h3>県内での1人当たり消費</h3><p class="big-number" style="color:var(--pink)">32,067<small>円</small></p><p class="micro">観光庁公式集計。費用回答2,391件。別府市の値ではありません。団体・パック参加費の県内収入分を含み、都道府県間の交通費は含みません。</p></article><article>'+bars([(x['fee'],x['yen_per_visitor']) for x in f['fees']],14000,'円',C[0])+'</article></div>'
body+=detail('全目的と観光・レジャー目的の支出費目',table('訪日外国人の大分県内消費単価（円/人）。宿泊費は日帰り等の0円も含む',['費目','全目的 n=2,391','観光・レジャー n=2,310'],[[x['fee'],fmt(x['yen_per_visitor']),fmt(fees[1]['fees'][i]['yen_per_visitor'])] for i,x in enumerate(f['fees'])]+[['総額',fmt(f['total_unit_yen']),fmt(fees[1]['total_unit_yen'])]])+'<p class="micro">公表費目の丸め合計は32,068円、総額32,067円と1円差があります。団体・パック参加費を除く民間集計とは定義が異なります。</p>'+link(S['oita_inbound_spending_2025']['source_url'],'観光庁・2025年都道府県別表1-2／2-2・大分県行'))
q=S['oita_questionnaire_2025fy'];reasons=q['prefecture_choice_reasons']
body+=detail('県を選んだ理由、泊数、再訪意向・不満の参考データ', '<p class="note">以下はいずれも県内20地点の2025年度アンケート。別府市の代表値ではありません。</p>'+table('大分県を選んだ理由・複数回答',['理由','県外・海外3,120人 %','海外居住200人 %'],[[r['reason'],r['all_pct'],r['foreign_pct']] for r in reasons['items']])+table('宿泊旅行者2,178人の大分県内泊数',['泊数','割合 %'],[[r['nights'],r['pct']] for r in q['nights_in_prefecture']['categories']])+'<p class="micro">県外に泊まり県内は0泊の人を含みます。3泊以上は上限がないため、この階級から正確な平均泊数は計算しません。県内宿泊先設問1,964人のうち別府を挙げた人は1,026人（52.2%、複数回答）。</p>'+table('県全体への改善希望・複数回答',['項目','全体4,942人 %','海外居住200人 %'],[[r['issue'],r['all_pct'],r['foreign_pct']] for r in q['improvements']['items']])+'<p class="micro">再来訪意向は全4,942人の94.1%。実際の再訪率ではありません。夜間観光の改善希望は海外居住者19人（9.5%）ですが、別府で帰りの足がない人数とは異なります。</p>'+link(q['url'],'県観光実態調査・9／25／27／33〜35頁'))
body+=detail('県質問紙の旅行費用は、足し算せず読む',table('旅行全体の1人当たり費用・円。県内だけの支出とは限らない',['区分','総費用','交通費','宿泊費','土産','飲食','入場','その他'],[[r['segment'],r['total'],r['transport'],r['lodging'] or '―',r['souvenir'],r['food'],r['admission'],r['other']] for r in q['costs']['items']],True)+'<p class="note warning">費目別の分母が公表されず、各費目平均の合計は総費用と一致しません。構成比や積上げ円グラフにはせず、原表の別指標として保持しています。</p>'+link(q['url']+'#page=31','県調査・30〜31頁'))
body+=photo('steam','湯けむり展望台から見る鉄輪温泉の湯けむりと山並み','湯けむり展望台 / 別府市・別府たび / 撮影年未記載の参考風景')
